  var stats = el('div', { class: 'stats' });
  stats.appendChild(statTile('Total atribuído (jul/2026+)', formatMoeda(totalGeral - totalSemAuditor), (porAuditor.length - (mapaAud['Sem auditor definido'] ? 1 : 0)) + ' auditor(es)'));
